// Authored arena tiles (R1-T3, D-057). The SVG sources are embedded in arena-art-data.js (generated by tools/gen-arena-art.js).
// A.tile(id, role, k) returns { w, h, cv, k } in metres and px per metre, or null while the image decodes or when the hood has
// no authored tile for that role; callers then use the baked canvas tile (istanbul-themes.js). When an image finishes
// decoding the theme cache is flushed once so the next frame picks up the art. View only; the sim never reads this.
P.ArenaArt = (function () {
  var A = {}, IMG = {}, RASTER = {}, pending = 0, flushT = 0;

  function load() {
    var data = P.ArenaArtData || {};
    Object.keys(data).forEach(function (id) {
      Object.keys(data[id]).forEach(function (role) {
        var d = data[id][role], im = new Image();
        pending++;
        im.onload = function () {
          IMG[id + '|' + role] = im; RASTER = {};
          if (--pending === 0 && P.Themes && P.Themes.flush) P.Themes.flush();
        };
        im.onerror = function () { pending--; };
        im.src = 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(d.svg);
      });
    });
  }

  A.has = function (id, role) { return !!(P.ArenaArtData && P.ArenaArtData[id] && P.ArenaArtData[id][role]); };
  A.tile = function (id, role, k) {
    var key = id + '|' + role, im = IMG[key];
    if (!im) return null;
    var rk = key + '|' + k, t = RASTER[rk];
    if (t) return t;
    var d = P.ArenaArtData[id][role], cv = document.createElement('canvas');
    cv.width = Math.ceil(d.w * k); cv.height = Math.ceil(d.h * k);
    cv.getContext('2d').drawImage(im, 0, 0, cv.width, cv.height);
    t = RASTER[rk] = { w: d.w, h: d.h, cv: cv, k: k, art: true };
    return t;
  };
  A.ready = function () { return pending === 0; };
  load();
  return A;
})();
